        let cs_high: u32 = 0;
        let chip_select: u32 = 0;
        if cs_high == 0 {
            self.base.ser.set(1 << chip_select);
        }
        // op_137: IF ((cs_high == 0x0) == 0x0) { W(B4, DW_SPI_SER) = 0x0 }
        if cs_high != 0 {
            self.base.ser.set(0);
        }

