    // Source: spi-dw-mmio.c:148
    // Role: write_config
    // -------------------------------------------------------------------
    pub fn dw_spi_sparx5_set_cs_body(&self, enable: u32) {
        // op_181: dwsmscc := VALUE(dwsmmio->priv)

        let cs: u32 = 0; // spi_get_chipselect(spi, 0) placeholder
        let cs_high: u32 = 0; // placeholder

        // op_182: IF (enable == 0x0) {
        //   TXWRITE[regmap] syscon@SPARX5_FORCE_ENA {1}
        //   TXWRITE[regmap] syscon@SPARX5_FORCE_VAL { (1 << cs) ^ 0xFFFFFFFF }
        // }
        if enable == 0 {
            // SPARX5_FORCE_ENA: write 1
            self.mmio_write32(0x0, 1);
            // SPARX5_FORCE_VAL: (1 << cs) ^ 0xFFFFFFFF
            let force_val = (1u32 << cs) ^ 0xFFFFFFFF;
            self.mmio_write32(0x4, force_val);
        }

        // op_184: IF ((enable == 0x0) == 0x0) {
        //   TXWRITE[regmap] syscon@SPARX5_FORCE_VAL { 0 ^ 0xFFFFFFFF = 0xFFFFFFFF }
        //   TXWRITE[regmap] syscon@SPARX5_FORCE_ENA {0}
        // }
        if enable != 0 {
            // SPARX5_FORCE_VAL: 0 ^ 0xFFFFFFFF = 0xFFFFFFFF
            self.mmio_write32(0x4, 0xFFFFFFFF);
            // SPARX5_FORCE_ENA: 0
            self.mmio_write32(0x0, 0);
        }

        // op_186: IF (cs_high == enable) { W(B4, DW_SPI_SER) = (0x1 << cs) }
        if cs_high == enable {
            self.base.ser.set(1 << cs);
        }
        // op_187: IF ((cs_high == enable) == 0x0) { W(B4, DW_SPI_SER) = 0x0 }
        if cs_high != enable {
            self.base.ser.set(0);
        }
    }

