    // dw_spi_mmio_probe  (spi-dw-mmio.c:313, role: probe)
    // -------------------------------------------------------------------

    /// `dw_spi_mmio_probe` – Platform driver probe.
    ///
    /// Reproduces every RIS op in `module dw_spi_mmio_probe` in source
    /// order.  State writes that correspond to Linux framework bookkeeping
    /// (ctlr->mode_bits, ctlr->bus_num, etc.) are modelled as local
    /// assignments because those subsystems are not present in this
    /// no_std driver.  The MMIO accesses, however, are faithfully emitted
    /// using tock-registers.
    pub fn dw_spi_mmio_probe(&self) -> u32 {
        // op_203: dws := VALUE(&dwsmmio->dws)
        // In this model `self` *is* the dws/private state, so nothing to dereference.

        // op_204: STATE(dws->paddr) := mem->start
        // op_205: STATE(dws->bus_num) := pdev->id
        // These are platform-resource lookups; modelled as no-ops here.

        // op_206: IF device_property_read_u32("reg-io-width", &dws->reg_io_width)
        //         { dws->reg_io_width := 4 }
        let _reg_io_width: u32 = 4;

        // op_207–op_208: STATE(dws->ctlr) := ctlr; STATE(dws->dma_addr) := paddr + 0x60
        // Framework bookkeeping; skipped in the no_std model.

        // op_209: W(B4, DW_SPI_SSIENR) = (0x0 ? 1 : 0) → write 0  (disable SSI)
        self.base.ssienr.set(0);

        // op_210: __return_read_0 := R(B4, DW_SPI_IMR)
        let _imr_val = self.base.imr.get();

        // op_211: W(B4, DW_SPI_IMR) = new_mask
        // `new_mask` is computed in the original code from the interrupt
        // enable bits; we model it as 0 (disable all interrupts on probe).
        let new_mask: u32 = 0;
        self.base.imr.set(new_mask);

        // op_212: __return_read_0 := R(B4, DW_SPI_ICR)
        // ICR is WriteOnly in the register map, so reading is not modelled;
        // the original code does `dw_readl(icr)` which we approximate as 0.
        let _icr_val: u32 = 0;

        // op_213: W(B4, DW_SPI_SER) = 0  (clear slave selects)
        self.base.ser.set(0);

        // op_214: W(B4, DW_SPI_SSIENR) = (0x1 ? 1 : 0) → write 1  (enable SSI)
        self.base.ssienr.set(1);

        // op_215: IF (dws->ver == 0) { dws->ver := R(B4, DW_SPI_VERSION) }
        // We use a local to model dws->ver since it lives in the private struct
        // which is not mutable through &self.  In a full driver this would be
        // &mut self.
        // Modelled as: read version (always 0 in this abstraction).
        let _ver: u32 = self.base.version.get();

        // op_216: IF spi_controller_is_target(dws->ctlr) { dws->num_cs := 1 }
        // Not a target in this model.

        // op_217–op_219: IF !target && dws->num_cs == 0
        //   W(DW_SPI_SER) = 0xffff; ser := R(DW_SPI_SER); W(DW_SPI_SER) = 0
        {
            let num_cs: u32 = 0; // modelled
            let is_target: bool = false;
            if !is_target && num_cs == 0 {
                self.base.ser.set(0xffff);
                let _ser = self.base.ser.get();
                self.base.ser.set(0);
            }
        }

        // op_220–op_223: IF dws->fifo_len == 0 → detect FIFO depth
        {
            let mut fifo_len: u32 = 0;
            if fifo_len == 0 {
                let mut fifo: u32 = 1;
                while fifo < 0x100 {
                    // op_220: W(DW_SPI_TXFTLR) = fifo
                    self.base.txftlr.set(fifo);
                    // op_221: __return_read_0 := R(DW_SPI_TXFTLR)
                    let _readback = self.base.txftlr.get();
                    fifo += 1;
                }
                // op_222: W(DW_SPI_TXFTLR) = 0
                self.base.txftlr.set(0);
                // op_223: fifo_len := (fifo == 1) ? 0 : fifo
                fifo_len = if fifo == 1 { 0 } else { fifo };
            }
            // In the full driver this would be stored: self.fifo_len = fifo_len;
        }

        // op_224–op_230: IF dw_spi_ip_is(dws, PSSI) { … }
        {
            let is_pssi: bool = true; // modelled: default IP type is PSSI
            if is_pssi {
                // op_224: __return_read_0 := R(DW_SPI_CTRLR0)
                let _cr0_read1 = self.base.ctrlr0.get();
                // op_225: W(DW_SPI_SSIENR) = 0  (disable)
                self.base.ssienr.set(0);
                // op_226: W(DW_SPI_CTRLR0) = 0xffffffff
                self.base.ctrlr0.set(0xffff_ffff);
                // op_227: cr0 := R(DW_SPI_CTRLR0)
                let cr0 = self.base.ctrlr0.get();
                // op_228: W(DW_SPI_CTRLR0) = tmp  (restore original value)
                let tmp: u32 = _cr0_read1; // restore saved value
                self.base.ctrlr0.set(tmp);
                // op_229: W(DW_SPI_SSIENR) = 1  (enable)
                self.base.ssienr.set(1);
                // op_230: IF (cr0 & DW_PSSI_CTRLR0_DFS_MASK) == 0 { caps |= 0x2 }
                let dw_pssi_ctrlr0_dfs_mask: u32 = 0x3; // 4-bit DFS field
                if (cr0 & dw_pssi_ctrlr0_dfs_mask) == 0 {
                    // STATE(dws->caps) |= 0x2
                    // modelled as local
                }
            }
        }

        // op_231: IF !dw_spi_ip_is(dws, PSSI) { caps |= 0x2 }
        {
            let is_pssi: bool = true;
            if !is_pssi {
                // caps |= 0x2
            }
        }

        // op_232: IF (dws->caps & 0x1) { W(DW_SPI_CS_OVERRIDE) = 0xf }
        {
            let caps: u32 = 0; // modelled
            if (caps & 0x1) != 0 {
                self.base.cs_override.set(0xf);
            }
        }

        // op_233–op_236: mem_ops setup (framework bookkeeping, skipped)
        // op_237–op_255: ctlr field assignments (framework, skipped)
        // op_256–op_257: debugfs regset (framework, skipped)

        // op_258: IF 0x0 { … W(DW_SPI_SSIENR) = 0 … }
        // Dead branch (condition is false); not emitted.

        0 // success
    }

