    // dw_spi_mmio_suspend  (spi-dw-mmio.c:393, role: suspend)
    // -------------------------------------------------------------------

    /// `dw_spi_mmio_suspend` – Power management suspend.
    ///
    /// Two MMIO writes: disable the SSI and clear the baud rate.
    pub fn dw_spi_mmio_suspend(&self) -> u32 {
        // op_259: W(B4, DW_SPI_SSIENR) = (0x0 ? 1 : 0) → write 0
        self.base.ssienr.set(0);
        // op_260: W(B4, DW_SPI_BAUDR) = 0
        self.base.baudr.set(0);
        0
    }

