    // dw_spi_mmio_resume  (spi-dw-mmio.c:410, role: resume)
    // -------------------------------------------------------------------

    /// `dw_spi_mmio_resume` – Power management resume.
    ///
    /// Re-initialises the controller, mirroring the probe init path.
    pub fn dw_spi_mmio_resume(&self) -> u32 {
        // op_261: W(DW_SPI_SSIENR) = 0  (disable)
        self.base.ssienr.set(0);

        // op_262: __return_read_0 := R(DW_SPI_IMR)
        let _imr_val = self.base.imr.get();

        // op_263: W(DW_SPI_IMR) = new_mask
        let new_mask: u32 = 0;
        self.base.imr.set(new_mask);

        // op_264: __return_read_0 := R(DW_SPI_ICR)
        // ICR is WriteOnly; modelled as 0.
        let _icr_val: u32 = 0;

        // op_265: W(DW_SPI_SER) = 0
        self.base.ser.set(0);

        // op_266: W(DW_SPI_SSIENR) = 1  (enable)
        self.base.ssienr.set(1);

        // op_267: IF (dws->ver == 0) { dws->ver := R(DW_SPI_VERSION) }
        let _ver: u32 = self.base.version.get();

        // op_268: IF spi_controller_is_target { num_cs := 1 }
        // Not target in this model.

        // op_269–op_271: IF !target && num_cs == 0
        {
            let num_cs: u32 = 0;
            let is_target: bool = false;
            if !is_target && num_cs == 0 {
                self.base.ser.set(0xffff);
                let _ser = self.base.ser.get();
                self.base.ser.set(0);
            }
        }

        // op_272–op_275: IF fifo_len == 0 → detect FIFO depth
        {
            let mut fifo_len: u32 = 0;
            if fifo_len == 0 {
                let mut fifo: u32 = 1;
                while fifo < 0x100 {
                    self.base.txftlr.set(fifo);
                    let _readback = self.base.txftlr.get();
                    fifo += 1;
                }
                self.base.txftlr.set(0);
                fifo_len = if fifo == 1 { 0 } else { fifo };
            }
        }

        // op_276–op_282: IF dw_spi_ip_is(PSSI)
        {
            let is_pssi: bool = true;
            if is_pssi {
                let _cr0_read1 = self.base.ctrlr0.get();
                self.base.ssienr.set(0);
                self.base.ctrlr0.set(0xffff_ffff);
                let cr0 = self.base.ctrlr0.get();
                let tmp: u32 = _cr0_read1;
                self.base.ctrlr0.set(tmp);
                self.base.ssienr.set(1);
                let dw_pssi_ctrlr0_dfs_mask: u32 = 0x3;
                if (cr0 & dw_pssi_ctrlr0_dfs_mask) == 0 {
                    // caps |= 0x2
                }
            }
        }

        // op_283: IF !dw_spi_ip_is(PSSI) { caps |= 0x2 }
        {
            let is_pssi: bool = true;
            if !is_pssi {
                // caps |= 0x2
            }
        }

        // op_284: IF (caps & 0x1) { W(DW_SPI_CS_OVERRIDE) = 0xf }
        {
            let caps: u32 = 0;
            if (caps & 0x1) != 0 {
                self.base.cs_override.set(0xf);
            }
        }

        0
    }

